C++ <pre><code>#include &lt;bits/stdc++.h&gt;
using namespace std;

pair&lt;int,int&gt; twoSum(const vector&lt;int&gt;&amp; nums, int target) {
    unordered_map&lt;int,int&gt; pos; // value -&gt; index
    for (int i = 0; i &lt; (int)nums.size(); ++i) {
        int need = target - nums[i];
        auto it = pos.find(need);
        if (it != pos.end()) return {it-&gt;second, i};
        pos[nums[i]] = i;
    }
    return {-1,-1}; // unreachable if guaranteed one solution
}
